<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مركز تحليلات البورصة المصرية</title>
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.rtl.min.css" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css">
<style>
:root{--bg:#090f1b;--surface:#111c2c;--surface2:#15243a;--line:#273950;--text:#edf4ff;--muted:#92a7c0;--cyan:#42d5ed;--green:#18c997;--red:#ff637a;--blue:#2c65ba}*{box-sizing:border-box}body{background:var(--bg);color:var(--text);font-family:Tajawal,sans-serif;font-size:15px}.page{max-width:1660px;margin:auto;padding:24px}.hero{background:linear-gradient(115deg,#142a44,#101c2d);border:1px solid var(--line);border-radius:20px;padding:25px 30px;display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.eyebrow{color:var(--cyan);font-weight:800}.hero h1{font-size:30px;font-weight:800;margin:7px 0}.muted{color:var(--muted)}.tabs{display:flex;gap:10px;margin-bottom:20px}.tabs a{color:#d3dfed;text-decoration:none;border:1px solid var(--line);border-radius:12px;padding:12px 20px;font-weight:700}.tabs a.active{background:linear-gradient(120deg,#1886a6,#285eb3);border-color:transparent;color:#fff}.layout{display:grid;grid-template-columns:310px minmax(0,1fr);gap:18px}.panel{background:linear-gradient(145deg,#13243a,#101b2b);border:1px solid var(--line);border-radius:18px;padding:20px;min-width:0}.runs{display:grid;gap:10px;max-height:76vh;overflow:auto}.run{display:block;color:var(--text);text-decoration:none;background:#152941;border:1px solid var(--line);padding:14px;border-radius:12px}.run.active,.run:hover{border-color:var(--cyan);background:#1a3550}.run small{display:block;color:var(--muted);margin-top:5px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.stat{background:#101d2e;border:1px solid var(--line);border-radius:15px;padding:15px}.stat small{display:block;color:var(--muted)}.stat b{display:block;color:#f1f6ff;font-size:25px;font-weight:800}.stat .ok{color:var(--green)}.stat .bad{color:var(--red)}.table-responsive{border:1px solid var(--line);border-radius:13px}table{min-width:1080px;margin:0!important;color:var(--text)!important}thead th{background:#0c1727!important;color:#bed0e5!important;border-color:var(--line)!important;white-space:nowrap}tbody td{background:#14243a!important;color:#eaf2fc!important;border-color:#2a3b52!important;vertical-align:middle}tbody tr:hover td{background:#1b304a!important}.code{font-weight:800;color:var(--cyan)}.ar-name{font-weight:700;color:#f4f7ff}.en-name{font-size:12px;color:var(--muted)}.status{display:inline-block;padding:5px 12px;border-radius:30px;font-weight:800;background:rgba(24,201,151,.16);color:var(--green)}.status.rejected{background:rgba(255,99,122,.16);color:var(--red)}.reason{min-width:180px;max-width:280px;white-space:normal;color:#dce7f5}.detail{color:var(--cyan);text-decoration:none;font-weight:800;white-space:nowrap}.search{max-width:390px;background:#0b1728!important;border:1px solid var(--line)!important;color:#fff!important}.search::placeholder{color:#8299b4}.company-logo{width:34px;height:34px;object-fit:contain;border-radius:8px;background:#fff}.empty{text-align:center;padding:35px;color:var(--muted)}.modal-content{background:#0d141f;color:var(--text);border:1px solid #35445a;border-radius:17px}.modal-header,.modal-footer{border-color:#2c394b}.modal-body{padding:22px}.modal-title{font-weight:800}.btn-close{filter:invert(1)}.nav-tabs{border-color:#344257;gap:4px}.nav-tabs .nav-link{color:#aebbd0;border:1px solid transparent;font-weight:700}.nav-tabs .nav-link.active{background:#182435;color:#f2f6ff;border-color:#344257 #344257 #182435}.plan-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.plan{background:#151c27;border:1px solid #303d50;border-radius:12px;padding:15px;min-height:85px}.plan small{display:block;color:#8998ad}.plan b{font-size:22px;color:#f0f4fb}.plan .positive{color:#00d4aa}.plan .negative{color:#ff687c}.section-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.metric-help{display:block;color:#9db2ca;font-size:12px;line-height:1.65;margin-top:7px}.help-dot{display:inline-flex;align-items:center;justify-content:center;width:17px;height:17px;border-radius:50%;background:#243b55;color:#65dff1;font-size:11px;margin-right:5px;cursor:help}.levels-wrap{display:grid;grid-template-columns:1fr 1fr;gap:14px}.level-list{padding:8px 12px;display:grid;gap:0}.level-item{border:0;border-bottom:1px solid #2d3c51;background:transparent;border-radius:0;padding:9px 2px}.level-price{display:flex;justify-content:space-between;align-items:center;color:#a9bed4;font-size:12px}.level-price strong{font-size:17px;color:#f2f7ff}.level-meta{display:flex;flex-wrap:wrap;gap:8px 16px;margin-top:9px;color:#9db2ca;font-size:12px}.level-meta b{color:#eaf2ff;margin-right:4px}.level-panel{border:1px solid #2d3c51;border-radius:12px;overflow:hidden;background:#101c2b}.level-title{padding:12px 14px;font-weight:800}.level-title.support{color:#18c997}.level-title.resistance{color:#ff637a}.level-table{width:100%;min-width:0!important;border-collapse:collapse}.level-table th,.level-table td{padding:10px 12px;border-bottom:1px solid #2b394c;text-align:right;white-space:nowrap}.level-table th{color:#91a8c1;background:#172536;font-size:12px}.level-table td{color:#edf4ff;background:#111e2e}.level-note{padding:10px 13px;color:#a7bad0;font-size:12px;line-height:1.7}@media(max-width:700px){.levels-wrap{grid-template-columns:1fr}}.data-card{background:#111d2b;border:1px solid #2d3c51;border-radius:10px;padding:12px;min-width:0}.data-card small{display:block;color:#8fa1b9}.data-card strong{display:block;color:#e9f1fb;overflow-wrap:anywhere;white-space:pre-wrap}.json{direction:ltr;text-align:left;white-space:pre-wrap;max-height:55vh;overflow:auto;background:#080f1a;color:#d8e8fa;padding:14px;border-radius:10px;font-size:12px}@media(max-width:950px){.layout{grid-template-columns:1fr}.runs{max-height:240px}.plan-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.page{padding:12px}.hero{padding:20px;display:block}.hero h1{font-size:24px}.stats{grid-template-columns:repeat(2,1fr)}.section-grid{grid-template-columns:1fr}}
</style></head><body><main class="page">
<header class="hero"><div><div class="eyebrow">EGX INTELLIGENCE · لوحة متابعة التحليلات</div><h1>مركز تحليلات البورصة المصرية</h1><div class="muted">استعرض نتائج التشغيلات وافتح تفاصيل السهم وأسباب القبول أو الرفض.</div></div><div><div class="eyebrow">نوع التحليل الحالي</div><strong>{{ $type==='intraday'?'التحليل اللحظي متعدد الأطر':'التحليل الفني العام' }}</strong></div></header>
<nav class="tabs"><a class="{{ $type==='analysis'?'active':'' }}" href="{{ route('results.index',['locale'=>request()->route('locale')??app()->getLocale(),'type'=>'analysis']) }}">التحليل العام</a><a class="{{ $type==='intraday'?'active':'' }}" href="{{ route('results.index',['locale'=>request()->route('locale')??app()->getLocale(),'type'=>'intraday']) }}">التحليل اللحظي Intraday</a></nav>
<div class="layout"><aside class="panel"><h5 class="fw-bold">سجل التحليلات</h5><p class="muted small">مرتبة من الأحدث إلى الأقدم حسب تاريخ قاعدة البيانات</p><div class="runs">@forelse($runs as $run)<a class="run {{ $selected&&$selected->id==$run->id?'active':'' }}" href="{{ route('results.index',['locale'=>request()->route('locale')??app()->getLocale(),'type'=>$type,'analysis_id'=>$run->id]) }}"><strong>{{ $run->title }}</strong><small>{{ $run->created_at->format('Y-m-d hh:mm A') }} · {{ $run->stocks_count }} سهم · #{{ $run->id }}</small></a>@empty<div class="empty">لا توجد تشغيلات لهذا النوع.</div>@endforelse</div></aside>
<section class="panel">@if($selected)<div class="d-flex justify-content-between align-items-start flex-wrap gap-2"><div><div class="eyebrow">تفاصيل التشغيل</div><h3 class="fw-bold mb-1">{{ $selected->title }}</h3><span class="muted">{{ $selected->analysis_date }}</span></div><span class="status">{{ $type==='intraday'?'لحظي':'عام' }}</span></div>
<div class="stats"><div class="stat"><small>إجمالي الأسهم</small><b>{{ count($stocks) }}</b></div><div class="stat"><small>مقبول / مؤهل</small><b class="ok">{{ count(array_filter($stocks,fn($s)=>$s['_accepted'])) }}</b></div><div class="stat"><small>مرفوض</small><b class="bad">{{ count(array_filter($stocks,fn($s)=>!$s['_accepted'])) }}</b></div><div class="stat"><small>تاريخ التشغيل</small><b style="font-size:18px">{{ $selected->analysis_date }}</b></div></div>
<div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><h5 class="fw-bold m-0">نتائج الأسهم</h5><input id="stockSearch" class="form-control search" placeholder="ابحث بكود السهم أو الاسم العربي أو الإنجليزي"></div>
<div class="table-responsive"><table class="table align-middle"><thead><tr><th>السهم / الشركة</th><th>الحالة</th><th>الإشارة / الاتجاه</th><th>السعر</th><th>الدخول</th><th>وقف الخسارة</th><th>الهدف الأول</th><th>الدرجة</th><th>السبب / الملاحظة</th><th></th></tr></thead><tbody id="stockRows">
@forelse($stocks as $s)<tr data-search="{{ $s['_search'] }}"><td><div class="d-flex align-items-center gap-2">@if($s['_logo'])<img class="company-logo" src="{{ $s['_logo'] }}" onerror="this.style.display='none'">@endif<div><div class="code">{{ $s['_symbol'] }}</div><div class="ar-name">{{ $s['_arabic'] ?: $s['_english'] }}</div>@if($s['_arabic']&&$s['_english'])<div class="en-name">{{ $s['_english'] }}</div>@endif</div></div></td><td><span class="status {{ $s['_accepted']?'':'rejected' }}">{{ $s['_accepted']?'مقبول':'مرفوض' }}</span></td><td>{{ $s['_signal_ar'] }}</td><td>{{ data_get($s,'feed.last_trade_price',$s['last_trade_price']??'—') }}</td><td>{{ $type==='intraday'?($s['entry']??'—'):($s['entry_price']??'—') }}</td><td>{{ $s['stop_loss']??'—' }}</td><td>{{ $type==='intraday'?($s['target_1']??'—'):($s['target1']??'—') }}</td><td>{{ $type==='intraday'?($s['signal_strength']??'—'):($s['opportunity_score']??'—') }}</td><td class="reason">{{ $s['_reason_ar'] }}</td><td><button class="btn btn-sm btn-outline-info" onclick='openStock(@json($s),@json($type))'>التفاصيل ←</button></td></tr>@empty<tr><td colspan="10" class="empty">لا توجد بيانات.</td></tr>@endforelse</tbody></table></div>
@else<div class="empty">لا توجد تشغيلات مسجلة لهذا النوع.</div>@endif</section></div></main>
<div class="modal fade" id="stockModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title"><i class="fa-solid fa-chart-column ms-2"></i><span id="mSymbol"></span></h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body">
<ul class="nav nav-tabs" role="tablist"><li class="nav-item"><button class="nav-link active" data-bs-toggle="tab" data-bs-target="#mPlan">خطة التداول</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#mSpeed">السرعة / التداول السريع</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#mTrend">الاتجاه</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#mSupply">العرض والطلب</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#mFull">التحليل الكامل</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#mRaw">JSON</button></li></ul>
<div class="tab-content"><div class="tab-pane fade show active pt-3" id="mPlan"><div class="plan-grid" id="mPlanGrid"></div><div class="data-card mt-3"><small>قرار التحليل وسبب القبول أو الرفض</small><strong id="mReason" class="mt-2"></strong></div></div><div class="tab-pane fade pt-3" id="mSpeed"><div class="section-grid" id="mSpeedGrid"></div></div><div class="tab-pane fade pt-3" id="mTrend"><div class="section-grid" id="mTrendGrid"></div></div><div class="tab-pane fade pt-3" id="mSupply"><div class="levels-wrap"><section class="level-panel"><div class="level-title support">↓ مستويات الدعم</div><div id="mSupports"></div></section><section class="level-panel"><div class="level-title resistance">↑ مستويات المقاومة</div><div id="mResistances"></div></section></div><div class="section-grid mt-3" id="mSupplyGrid"></div></div><div class="tab-pane fade pt-3" id="mFull"><div class="section-grid" id="mFullGrid"></div></div><div class="tab-pane fade pt-3" id="mRaw"><pre class="json" id="mJson"></pre></div></div></div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal">إغلاق</button></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>
const labels={last_trade_price:'السعر الحالي',entry_low:'أقل الدخول',entry_high:'أعلى الدخول',entry:'سعر الدخول',entry_price:'سعر الدخول',stop_loss:'وقف الخسارة',target_1:'الهدف الأول',target_2:'الهدف الثاني',target1:'الهدف الأول',target2:'الهدف الثاني',risk_reward:'العائد إلى المخاطرة',risk_reward_t1:'العائد/المخاطرة للهدف الأول',risk_reward_t2:'العائد/المخاطرة للهدف الثاني',signal_strength:'قوة الإشارة',opportunity_score:'درجة الفرصة',opportunity_grade:'تصنيف الفرصة',speed_score:'درجة السرعة',fast_score:'درجة التداول السريع',fast_class:'تصنيف السرعة',fast_trade:'تداول سريع',trend:'الاتجاه',trend_score:'درجة الاتجاه',swings:'القمم والقيعان',hh:'قمة أعلى HH',hl:'قاع أعلى HL',lh:'قمة أقل LH',ll:'قاع أقل LL',bos:'كسر هيكل السوق BOS',bullish_bos:'عدد الكسور الصاعدة',bearish_bos:'عدد الكسور الهابطة',choch:'تغير السلوك CHoCH',liquidity_sweep:'سحب السيولة',supports:'مستويات الدعم',resistances:'مستويات المقاومة',selected_support:'الدعم المختار',selected_resistance:'المقاومة المختارة',volume_score:'درجة الحجم',relative_volume:'الحجم النسبي',relative_volume_classification:'تصنيف الحجم النسبي',average_volume:'متوسط الحجم',last_volume:'آخر حجم',volume_trend:'اتجاه الحجم',volume_slope:'ميل الحجم',accumulation_score:'درجة التجميع',bullish_volume:'حجم شرائي',bearish_volume:'حجم بيعي',accumulation_state:'حالة التجميع',atr:'متوسط المدى الحقيقي ATR',atr_percent:'نسبة ATR',support_rank:'ترتيب الدعم',entry_score:'درجة الدخول',support_bounce_score:'درجة الارتداد من الدعم',support_bounce_signal:'إشارة الارتداد',support_confirmed:'تأكيد الدعم',support_bounce:'الارتداد من الدعم',entry_distance:'المسافة عن الدخول',entry_timeframe:'الإطار الزمني للدخول',strategy:'الاستراتيجية',signal:'الإشارة',signal_reason:'سبب الإشارة',reason:'السبب',status:'الحالة',timeframes:'الأطر الزمنية',hierarchy:'توافق الأطر الزمنية',strategies:'الاستراتيجيات',data_errors:'أخطاء البيانات',candles:'الشموع',trade:'خطة التداول',feed:'بيانات السوق',high_price:'أعلى سعر',low_price:'أقل سعر',open_price:'سعر الافتتاح',previous_close:'إغلاق سابق',last_change_prc:'نسبة التغير',total_volume:'إجمالي حجم التداول',total_value:'قيمة التداول',total_trades:'عدد العمليات',symbol:'رمز السهم'};
const explanations={strength:'كلما زادت قوة المستوى زادت أهميته التاريخية وفق بيانات المحرك، لكنها لا تضمن ارتداد السعر.',touches:'عدد مرات اختبار السعر للمستوى. التكرار قد يدعم أهميته، لكن كثرة الاختبارات قد تضعفه إذا تم كسره.',group_touches:'عدد اللمسات داخل مجموعة مستويات متقاربة؛ زيادته قد تعزز أهمية المنطقة ولا تعني ضمان التفاعل.',distance_percent:'المسافة المئوية عن السعر الحالي. قرب الدعم قد يجعله ذا صلة بالحركة الحالية، وقرب المقاومة يعني وجود حاجز سعري قريب.',swing_index:'مؤشر ترتيب داخلي للمستوى حسب محرك التحليل، وليس احتمال نجاح.',bos:'عدد مرات كسر هيكل السوق المرصودة. يجب فصل الصاعد عن الهابط قبل تفسيره.',choch:'إشارة تغير سلوك محتملة، وليست انعكاسًا مؤكدًا بمفردها.',trend_score:'درجة مركبة للاتجاه؛ لا تعني وحدها أن الدخول مناسب.',opportunity_score:'تقييم نسبي من محرك التحليل، وليس نسبة احتمالية ربح.',risk_reward:'نسبة العائد المحتمل إلى المخاطرة؛ الأعلى أفضل حسابيًا مع بقاء احتمال الخسارة.',atr_percent:'مقياس التذبذب النسبي؛ ارتفاعه يعني حركة أوسع ومخاطرة محتملة أكبر.',relative_volume:'مقارنة حجم التداول بمتوسطه؛ الارتفاع قد يؤكد الاهتمام ويُقرأ مع اتجاه السعر.'};
function val(v){if(v===null||v===undefined||v==='')return '—';if(typeof v==='boolean')return v?'نعم':'لا';if(typeof v==='object')return JSON.stringify(v,null,2);return String(v)}
function explain(k,v){const n=Number(v);if(Number.isFinite(n)&&['strength','signal_strength','opportunity_score','trend_score','volume_score','speed_score','fast_score'].includes(k))return n>=80?'مرتفع: قراءة قوية نسبيًا على مقياس المحرك، وليست ضمانًا.':n>=60?'متوسط إلى جيد: يحتاج تأكيدًا من بقية المؤشرات.':'منخفض نسبيًا: قراءة أضعف على هذا المقياس.';if(Number.isFinite(n)&&['risk_reward','risk_reward_t1','risk_reward_t2'].includes(k))return n>=2?'عائد/مخاطرة مرتفع حسابيًا.':n>=1.5?'نسبة متوسطة؛ راجع الوقف والأهداف.':'نسبة محدودة؛ العائد قريب من مقدار المخاطرة.';if(k==='atr_percent'&&Number.isFinite(n))return n>=5?'تذبذب مرتفع نسبيًا؛ راعِ الوقف وحجم المركز.':n>=2?'تذبذب متوسط نسبيًا.':'تذبذب منخفض نسبيًا.';return explanations[k]||''}
function card(k,v){const tip=explain(k,v);const display=['selected_support','selected_resistance'].includes(k)&&v&&typeof v==='object'?(v.price??v.level??v.value??'—'):v;return `<div class="data-card"><small>${labels[k]||k.replaceAll('_',' ')} ${tip?`<span class="help-dot" title="${tip.replaceAll('"','&quot;')}">؟</span>`:''}</small><strong>${val(display)}</strong>${tip?`<span class="metric-help">${tip}</span>`:''}</div>`}
function plan(k,v){const tip=explain(k,v);return `<div class="plan"><small>${labels[k]||k} ${tip?`<span class="help-dot" title="${tip.replaceAll('"','&quot;')}">؟</span>`:''}</small><b>${val(v)}</b>${tip?`<span class="metric-help">${tip}</span>`:''}</div>`}
function levelRows(levels,kind){if(!Array.isArray(levels)||!levels.length)return `<div class="level-note">لا توجد مستويات ${kind==='support'?'دعم':'مقاومة'} مسجلة.</div>`;return `<div class="level-list">${levels.map((x,i)=>{const o=x&&typeof x==='object'?x:{price:x};const price=o.price??o.level??o.value;const strength=o.strength;const touches=o.touches??o.group_touches;const distance=o.distance_percent;const src=o.source;return `<article class="level-item"><div class="level-price">${kind==='support'?'دعم':'مقاومة'} ${i+1}<strong>${val(price)}</strong></div><div class="level-meta"><span>القوة <b>${val(strength)}</b></span><span>عدد اللمسات <b>${val(touches)}</b></span><span>المسافة <b>${distance===undefined?'—':val(distance)+'%'}</b></span></div>${src?`<div class="level-note">المصدر: ${val(src)}</div>`:''}</article>`}).join('')}</div><div class="level-note">${kind==='support'?'مستويات الدعم مناطق محتملة لظهور طلب، وليست ضمانًا للارتداد.':'مستويات المقاومة مناطق محتملة لظهور عرض أو ضغط بيع، وليست ضمانًا للهبوط.'}</div>`}
function openStock(s,type){const modal=document.getElementById('stockModal');if(!modal){console.error('stockModal is missing');return}const put=(id,html)=>{const el=modal.querySelector('#'+id);if(el)el.innerHTML=html;else console.warn('Missing modal element:',id)};const putText=(id,value)=>{const el=modal.querySelector('#'+id);if(el)el.textContent=value;else console.warn('Missing modal element:',id)};putText('mSymbol',(s._symbol||s.symbol)+' · '+(s._arabic||s.arb_name||s._english||s.eng_name||''));const feed=s.feed||{};const get=(...keys)=>{for(const k of keys)if(s[k]!==undefined&&s[k]!==null)return s[k];return feed[keys[0]]??null};
let fields=type==='intraday'?['last_trade_price','entry','stop_loss','target_1','target_2','risk_reward_t1','signal_strength']:['last_trade_price','entry_low','entry_high','entry_price','stop_loss','target1','target2','risk_reward','opportunity_score','opportunity_grade'];
put('mPlanGrid',fields.map(k=>plan(k,get(k))).join(''));
putText('mReason',s.signal_reason||s.reason||s.rejection_reason||s.reject_reason||'لا توجد ملاحظة تفصيلية مسجلة في ملف التحليل.');

const groups={mSpeed:['speed_score','speed_class','fast_score','fast_class','fast_trade','support_bounce_score'],mTrend:['trend','trend_score','hh','hl','lh','ll','bos','bullish_bos','bearish_bos','choch','liquidity_sweep'],mSupply:['supports','support_levels','demand_levels','resistances','resistance_levels','supply_levels','selected_support','selected_resistance','support_rank','support_bounce_signal','support_confirmed'],mFull:['status','signal','strategy','entry_timeframe','signal_strength','opportunity_score','volume_score','relative_volume','relative_volume_classification','average_volume','last_volume','volume_trend','accumulation_score','accumulation_state','atr','atr_percent','entry_distance','hierarchy','strategies','timeframes','data_errors']};
Object.entries(groups).forEach(([id,keys])=>{if(id==='mSupply'){const supports=s.supports||s.support_levels||s.demand_levels||[];const resistances=s.resistances||s.resistance_levels||s.supply_levels||[];put(id,`<div class="levels-wrap"><section class="level-panel"><div class="level-title support">مستويات الدعم</div>${levelRows(supports,'support')}</section><section class="level-panel"><div class="level-title resistance">مستويات المقاومة</div>${levelRows(resistances,'resistance')}</section></div><div class="section-grid mt-3">${keys.filter(k=>!['supports','support_levels','demand_levels','resistances','resistance_levels','supply_levels'].includes(k)&&s[k]!==undefined).map(k=>card(k,s[k])).join('')}</div>`);return}put(id,keys.filter(k=>s[k]!==undefined).map(k=>card(k,s[k])).join('')||'<div class="muted">لا توجد بيانات مسجلة في هذا القسم لهذا السهم.</div>')});
putText('mJson',JSON.stringify(s,null,2));bootstrap.Modal.getOrCreateInstance(modal).show()}
document.getElementById('stockSearch')?.addEventListener('input',e=>{const q=e.target.value.toLocaleLowerCase();document.querySelectorAll('#stockRows tr[data-search]').forEach(tr=>tr.hidden=!tr.dataset.search.includes(q))});
</script></body></html>
